      "「父からはとけいをいただきませんでした」同樣對父親使用「いただく」雖方向正確，但語意上（沒收到手錶）不是典型例句，此處不是最合適的用法，錯誤。",
      "「先生にじしょをいただきました」意思是「從老師那裡收到了辭典」，對老師（地位較高者）使用「いただく」是最典型自然的敬語用法，為正解。",
      "「あついうちにスープをいただいてください」對客人使用「いただいて」是誤用（請對方吃喝應該用「召し上がって」），方向錯誤，錯誤。"
