    "optionExplanations": [
      "「あしたはだめです。よていがあります。」（明天不行，我有安排了）——「だめ」在此用來表示「不行、不可以」，用法正確，為正解。",
      "「わたしのだめがやっとなおりました。」——「だめ」不是名詞，不能當作主語使用（可能想表達的是身體或物品，但不能用「だめ」），用法錯誤。",
      "「きのうは時間をだめにつかってしまった。」——此處應使用「むだ（浪費）」而非「だめ」，「だめにつかう」不是自然的搭配，用法錯誤。",
      "「テレビを買おうとしたら、あと2000円だめだった。」——此處應使用「たりない（不夠）」而非「だめ」，用法錯誤。"
    ]
