      "「毎日へやをかたづけなさい。」——「部屋を片付ける（整理房間）」是「かたづける」最自然典型的用法，為正解。",
      "「毎日カーテンをかたづけなさい。」——「カーテン（窗簾）」不是可以「片付ける」的對象，用法錯誤。",
      "「毎日きょうみをかたづけなさい。」——「興味（興趣）」是抽象概念，不能「片付ける」，用法錯誤。"
