    "optionExplanations": [
      "「こまったときにはすぐにあやまってください。」——遇到困難時應該是「相談する（商量）」或「助けてもらう（尋求幫助）」，不是「謝る（道歉）」，用法錯誤。",
      "「友だちにおくりものをもらったので、あやまりました。」——收到禮物應該「お礼を言う（道謝）」而非「謝る（道歉）」，用法錯誤。",
      "「てつだってもらったときにはかならずあやまってください。」——受到幫助應該「お礼を言う（道謝）」而非「謝る（道歉）」，用法錯誤。",
      "「しらない人の足をふんでしまったので、あやまりました。」——踩到陌生人的腳而道歉，是「謝る」最典型自然的用法，為正解。"
    ]
