      "「お湯をわかしてコーヒーを飲みましょう」（燒開水泡咖啡喝吧）是「わかす」最自然的用法，為正解。",
      "「ストーブをわかして」暖爐應該用「つける」（打開），不用「わかす」，錯誤。"
