    "meaning": {
      "prompt": "落ち着く",
      "options": [
        "電車が駅に落ち着いたら電話をください。",
        "この商品は人気がなくて、棚にずっと落ち着いている。",
        "家のかぎが穴に落ち着いた。",
        "火事のとき落ち着いて行動しよう。"
      ],
      "answerIndex": 3
    },
    "optionExplanations": [
      "「電車が駅に落ち着いたら」搭配錯誤，「落ち着く」不用於電車進站，應說「電車が駅に着いたら」。",
      "「棚にずっと落ち着いている」用法不自然，商品滯銷不用「落ち着く」表達。",
      "「かぎが穴に落ち着いた」用法不自然，鑰匙插入孔洞不用「落ち着く」表達。",
      "「落ち着いて行動しよう」意為冷靜、沉著地行動，正解，符合「落ち着く」（心情沉著冷靜）的核心語意。"
    ]
