      "應使用「流れて」（計畫流產、告吹）：突然有事所以旅行計畫告吹了，用「ころんで」語意不合。",
      "應使用「倒れた」（倒下）：颱風把院子裡的樹吹倒了，用「ころんだ」（人跌倒的動作）不合樹木倒下的語境。",
      "正解。「階段でころんでけがをした」＝「在樓梯上摔倒受了傷」，「ころぶ」（跌倒）用法正確。"
