      "「中村選手は山口選手を通り過ぎて、1位でゴールに入った。」用法錯誤，比賽中超越對手應用「追い越して」（超越），不用「通り過ぎる」。",
      "「夜の10時を通り過ぎていたので、レストランは閉まっていた。」用法錯誤，時間超過應用「過ぎた」（過了），不用「通り過ぎる」。"
