      "「週末はいつも家族で海を訪問しています。」用法錯誤，去海邊遊玩應用「海に行って」（去海邊），不用「訪問」。",
      "「突然海外旅行のチャンスが訪問しました。」用法錯誤，機會到來應用「訪れました」（造訪、到來，但此處主語需為人拜訪某處，用法本身也不自然），不用「訪問」。"
