    "optionExplanations": [
      "「公園の中を経由するとちょっと近道になる」誤用，單純「經過、通過」某處抄近路應該用「通る」，錯誤。",
      "正解。「市役所を経由して駅へ向かいます」（途經市政府開往車站）是「経由」（途經、經過某地前往目的地）最典型、正確的用法。",
      "「会社員を経由して大学に入った」誤用，經歷（曾當過會社員後上大學）應該用「経験」，錯誤。",
      "「昼休みを経由して午後まで続いた」誤用，時間上的連續應該用「挟んで」（夾著、跨過），錯誤。"
    ]
